import { OrderRepository } from '../domain/repositories';
import { Order, OrderState } from '../domain/types';

export class InMemoryOrderRepository implements OrderRepository {
  private orders: Map<string, Order> = new Map();

  save(order: Order): void {
    this.orders.set(order.id, { ...order, items: [...order.items] });
  }

  getById(id: string): Order | null {
    const order = this.orders.get(id);
    if (!order) return null;
    return { ...order, items: [...order.items] };
  }

  getAll(): Order[] {
    return Array.from(this.orders.values()).map(order => ({
      ...order,
      items: [...order.items],
    }));
  }

  getByState(state: OrderState): Order[] {
    return Array.from(this.orders.values())
      .filter(order => order.state === state)
      .map(order => ({ ...order, items: [...order.items] }));
  }
}

